const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  try {
    // 1. Geometry & Time Definitions
    const admin2 = ee.FeatureCollection("FAO/GAUL/2015/level2");
    const salta = admin2.filter(ee.Filter.and(
      ee.Filter.eq('ADM0_NAME', 'Argentina'),
      ee.Filter.eq('ADM1_NAME', 'Salta')
    ));

    if (salta.size().getInfo() === 0) {
      console.log("C1: Salta Province not found.");
      console.log("C1");
      return;
    }
    const geometry = salta.geometry();

    const gfc = ee.Image('UMD/hansen/global_forest_change_v1_8'); // GFC dataset up to 2020 (v1.8 includes 2019 loss)
    const treeCover2000 = gfc.select('treecover2000');
    const loss = gfc.select('loss');
    const lossYear = gfc.select('lossyear');

    // Define forest as pixels with >= 10% tree cover in 2000
    const treeCoverThreshold = 10; // Percent
    const initialForest = treeCover2000.gte(treeCoverThreshold); // Binary image: 1 if forest, 0 otherwise

    // Scale for area calculation (in meters). GFC resolution is ~30m, 1000m is good for regional analysis.
    const scale = 1000; 
    const projection = treeCover2000.projection(); // Use native projection

    // 2. Calculate Initial Forest Area (December 2000)
    // Area of initial forest within Salta Province, accounting for pixel area
    const initialForestAreaImage = initialForest.multiply(ee.Image.pixelArea());

    const initialForestStats = await initialForestAreaImage.reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: geometry,
      scale: scale,
      maxPixels: 1e9,
      crs: projection.crs(),
      crsTransform: projection.getInfo().transform,
    }).get('treecover2000').getInfo();

    const initialForest_km2 = initialForestStats / 1e6; // Convert m^2 to km^2

    // 3. Calculate Forest Loss Area (from 2001 to 2019)
    // Filter loss pixels that occurred up to and including 2019.
    // lossyear band values: 1 for 2001, ..., 19 for 2019.
    const loss2000to2019 = loss.and(lossYear.lte(19));

    // Calculate loss only for areas that were initially forest in 2000
    const relevantLoss = loss2000to2019.and(initialForest);
    const lossAreaImage = relevantLoss.multiply(ee.Image.pixelArea());

    const lossStats = await lossAreaImage.reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: geometry,
      scale: scale,
      maxPixels: 1e9,
      crs: projection.crs(),
      crsTransform: projection.getInfo().transform,
    }).get('loss').getInfo();

    const loss_km2 = lossStats / 1e6; // Convert m^2 to km^2

    // 4. Validation & Final Answer
    if (initialForest_km2 === null || isNaN(initialForest_km2) || loss_km2 === null || isNaN(loss_km2)) {
      console.log("C3: Calculation returned null or NaN.");
      console.log("C3");
      return;
    }

    if (initialForest_km2 === 0) {
      console.log("C2: No valid initial forest pixels found in Salta Province.");
      console.log("Initial Forest Area (2000): 0 km^2");
      console.log("C2");
      return;
    }

    console.log(`Salta Province, Argentina (Tree cover >= ${treeCoverThreshold}%):`);
    console.log(`Initial Forest Area (2000): ${initialForest_km2.toFixed(2)} km^2`);
    console.log(`Forest Loss (2001-2019): ${loss_km2.toFixed(2)} km^2`);
    console.log(`Percentage Loss of Initial Forest: ${((loss_km2 / initialForest_km2) * 100).toFixed(2)}%`);

    if (loss_km2 > 0) {
      console.log("A");
    } else {
      console.log("B");
    }

  } catch (error) {
    console.log("D: An error occurred during analysis:", error);
    console.log("D");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
